/**
 * Admin Dashboard Page
 */

import React, { useState, useEffect } from 'react';
import LoadingSpinner from '../components/LoadingSpinner';
import api from '../services/api';
import './AdminDashboard.css';

const AdminDashboard = () => {
  const [dashboard, setDashboard] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchDashboard();
  }, []);

  const fetchDashboard = async () => {
    try {
      const response = await api.get('/dashboard/admin');
      setDashboard(response.data.dashboard);
      setError('');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to fetch dashboard');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <LoadingSpinner message="Loading admin dashboard..." />;
  }

  if (!dashboard) {
    return <div className="error-container">{error}</div>;
  }

  return (
    <div className="admin-dashboard-page">
      <div className="admin-container">
        <h1>Admin Dashboard</h1>

        {/* Stats Grid */}
        <div className="stats-grid">
          <div className="stat-card">
            <span className="stat-icon">👥</span>
            <div className="stat-content">
              <h3>Total Users</h3>
              <p className="stat-value">{dashboard.totalUsers}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">📅</span>
            <div className="stat-content">
              <h3>Total Events</h3>
              <p className="stat-value">{dashboard.totalEvents}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">🎫</span>
            <div className="stat-content">
              <h3>Total Bookings</h3>
              <p className="stat-value">{dashboard.totalBookings}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">💰</span>
            <div className="stat-content">
              <h3>Total Revenue</h3>
              <p className="stat-value">₹{dashboard.totalRevenue}</p>
            </div>
          </div>
        </div>

        {/* Bookings by Status */}
        <div className="chart-section">
          <h2>Bookings by Status</h2>
          <div className="status-overview">
            {Object.entries(dashboard.bookingsByStatus || {}).map(([status, count]) => (
              <div key={status} className="status-item">
                <span className="status-name">{status}</span>
                <span className="status-count">{count}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Recent Bookings */}
        <div className="table-section">
          <h2>Recent Bookings</h2>
          <div className="table-wrapper">
            <table className="admin-table">
              <thead>
                <tr>
                  <th>User</th>
                  <th>Event</th>
                  <th>Tickets</th>
                  <th>Amount</th>
                  <th>Date</th>
                </tr>
              </thead>
              <tbody>
                {dashboard.recentBookings?.map((booking, idx) => (
                  <tr key={idx}>
                    <td>{booking.userName}</td>
                    <td>{booking.eventName}</td>
                    <td>{booking.tickets}</td>
                    <td>₹{booking.amount}</td>
                    <td>{new Date(booking.date).toLocaleDateString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Top Events */}
        <div className="table-section">
          <h2>Top Events</h2>
          <div className="table-wrapper">
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Event Name</th>
                  <th>Bookings</th>
                  <th>Revenue</th>
                </tr>
              </thead>
              <tbody>
                {dashboard.topEvents?.map((event, idx) => (
                  <tr key={idx}>
                    <td>{event.eventName}</td>
                    <td>{event.bookings}</td>
                    <td>₹{event.revenue}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
